```TypeScript
import { ApplicationCommandOptionTypes, ChatInputApplicationCommandData, CommandInteraction, EmbedBuilder, EmbedFooterBuilder, EmbedThumbnailBuilder, GuildMember, MessageEmbed, TextChannel, User } from 'discord.js';
import { client, commands } from '../index';

export default {
  data: {
    name: 'ban',
    description: 'Bans a user from the server.',
    options: [
      {
        name:'member',
        description: 'Select a member to ban.',
        type: ApplicationCommandOptionTypes.USER,
        required: true,
      },
      {
        name:'reason',
        description: 'Reason for the ban.',
        type: ApplicationCommandOptionTypes.STRING,
      },
    ],
  },

  async execute(interaction: CommandInteraction) {
    const { guild, members } = interaction;

    if (!guild ||!members.has(interaction.options.getMember('member')))
      return interaction.reply({ content: 'Invalid member provided.', ephemeral: true });

    const targetUser = interaction.options.getUser('member');
    const reason = interaction.options.getString('reason') || 'No reason provided.';
    const mod = interaction.user;

    /**
     * Only server admins may use this command.
     */
    if (!interaction.member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({ content: 'You do not have permission to perform this action!', ephemeral: true });
    }

    const targetMember = guild.members.cache.get(targetUser.id);

    const embed = new EmbedBuilder()
     .setTitle(`Banning ${targetUser.username}`)
     .setDescription(`${reason}\n\n**Moderator:** ${mod.username} (${mod.id})`)
     .setTimestamp(new Date())
     .setColor('#FF0000')
     .setImage(`${targetUser.displayAvatarURL({
        format: 'png'
      })}`);

    if (targetMember) {
      const sendMethod = targetMember.send
       ? async (): Promise<MessageEmbed> => await targetMember.send({ embeds: [embed] })
        : () => null;

      await guild.members.ban(targetUser.id, { days: 7, reason }).catch((err) => {
        console.error(err.message);

        if (sendMethod)
          sendMethod().catch(err => {
            console.error(`Error sending DM to banned user: ${err}`);
          });

        interaction.reply({ content: 'An error occurred while attempting to ban the user.', ephemeral: true });
      });

      const banner = new EmbedBuilder()
       .setTitle(`Banned ${targetUser.username}`)
       .addFields([
          {
            name: '@mention',
            value: `${targetUser.toString()}`
          },
          {
            name: 'Reason',
            value: `\`${reason}\``
          },
          {
            name: 'Moderator',
            value: `${mod.toString()} (<@${mod.id}>)`
          }
        ])
       .setFooter({ text: 'Ban Log', iconURL: guild.iconURL({ dynamic: true }) })
       .setThumbnail(new EmbedThumbnailBuilder().setURL(targetUser.displayAvatarURL()))
       .setColor('#FF0000');

      const channel = guild.channels.cache.get('TEXT_CHANNEL_ID_HERE') as TextChannel; // replace TEXT_CHANNEL_ID_HERE with your actual channel ID

      await channel.send({ embeds: [banner] });
    }

    // Respond with a confirmation message after banning
    interaction.reply({ embeds: [embed], ephemeral: false }).catch((err) => {
      console.log(err.message);
    });
  }
};
```

You'll need to update `TEXT_CHANNEL_ID_HERE` to match your desired Discord channel for logging the ban message.

